"""Data facts: the findings a page's writer delivers, with the code behind each, run again by us.

facts.json is a list of facts:

    {"id": "west-returns-most",
     "claim": "Among regions with at least 100 orders, the West has the highest return rate, 19%, against 14% in the East and 13% in the North.",
     "tables": {"orders": "data/orders.csv"},
     "code": "orders[orders.region.map(orders.region.value_counts()) >= 100].groupby('region').returned.apply(lambda s: (s == 'yes').mean())"}

`tables` names the files (paths from the writer's folder, as data/orders.csv)
that are read with pd.read_csv into variables; `code` is one Python expression over them, with pd
and np available. Every fact's code is evaluated as written, in the page agent's
sandbox (report-gepa/agent/sandbox.sh: no network, nothing but the workspace),
since it is code someone else wrote, and its value is printed the way pandas
prints it.
"""

from __future__ import annotations

import json
import os
import shutil
import subprocess
import tempfile
from pathlib import Path

SANDBOX = Path(__file__).resolve().parents[3] / "report-gepa" / "agent" / "sandbox.sh"
TIMEOUT = 600

RUN = r'''
import json
import numpy as np
import pandas as pd

pd.set_option("display.width", 200)
out = {}
for f in json.load(open("facts.json")):
    try:
        env = {"pd": pd, "np": np}
        env.update({name: pd.read_csv(path) for name, path in f["tables"].items()})
        value = eval(f["code"], env)
        out[f["id"]] = {"output": value.to_string() if hasattr(value, "to_string") else str(value)}
    except Exception as e:
        out[f["id"]] = {"error": f"{type(e).__name__}: {e}"[:300]}
print(json.dumps(out))
'''


class FactError(ValueError):
    """facts.json that cannot be read as a list of facts."""


def load(path: Path) -> list[dict]:
    try:
        facts = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as e:
        raise FactError(f"{path.name}: {e}") from e
    keys = ("id", "claim", "tables", "code")
    if not isinstance(facts, list) or not all(isinstance(f, dict) and all(f.get(k) for k in keys) for f in facts):
        raise FactError(f"{path.name}: not a list of facts with {', '.join(keys)}")
    return facts


def run(facts: list[dict], data: list[Path]) -> dict[str, dict]:
    """Every fact's printed value ("output") or why it failed ("error"), by id.
    `data` is what the writer found in data/: files and folders, by their own names."""
    with tempfile.TemporaryDirectory() as tmp:
        ws = Path(tmp)
        (ws / "data").mkdir()
        for p in data:
            if p.is_dir():
                shutil.copytree(p, ws / "data" / p.name, copy_function=os.link)
            else:
                os.link(p, ws / "data" / p.name)
        (ws / "facts.json").write_text(json.dumps(facts), encoding="utf-8")
        (ws / "run.py").write_text(RUN, encoding="utf-8")
        proc = subprocess.run([str(SANDBOX), str(ws), "python3 run.py"], capture_output=True, text=True, timeout=TIMEOUT)
    if proc.returncode != 0:
        return {f["id"]: {"error": f"the run failed: {proc.stderr.strip()[-300:]}"} for f in facts}
    return json.loads(proc.stdout.strip().splitlines()[-1])

"""Rubric items 1.1-1.3, trust: does the page run, and are its findings true to the data?

    PYTHONPATH=src:../report-bench/src .venv/bin/python -m report_bench.trust <evidence_dir> <facts.json> [--model m]

The page's writer delivers facts.json (facts.py): every finding as a claim and
the pandas code that computes it. The items, in order, each a veto:

- 1.1 renders: the capture opened the page and it showed text; a generated page
  also ran without errors. Published Pudding pages throw errors of their own
  (titletowns: "reading 'latitude'") and still work, so for them only the first
  part applies.
- 1.2 facts run: facts.json loads and every fact's code runs on the data.
- 1.3 claims hold: one model call reads each claim next to its code and what the
  code printed, and says whether they agree.

An item is checked only if the ones before it hold.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
from pathlib import Path

from . import facts as F
from .llm import LLM

MODEL = "deepseek-v4.1-flash"
MAX_TOKENS = 32768  # the reasoning counts too

PROMPT = """下面是一份数据报告给出的发现。每条发现有结论(claim),一段在数据上运行的 pandas 代码(code),和这段代码的输出(output)。

逐条判断结论和输出是否一致:
- ok:结论里的数字、比较、多少、趋势都和输出相符。四舍五入造成的出入不算不符。
- wrong:结论和输出矛盾，或者结论说的东西输出里没有，或者结论里的数和名字不是代码从表里算出来的，而是直接写在代码里的(比如代码就是一个写好的字符串、写好数值的 Series)。筛选条件、阈值、改名写在代码里没关系。

每条先在 basis 里写出输出里对应的数，再给 verdict。只输出 JSON:{"facts": [{"id": "...", "basis": "...", "verdict": "ok 或 wrong"}]}

{facts}
"""
PROMPT_HASH = hashlib.sha256(PROMPT.encode()).hexdigest()[:12]


def renders(ev: dict) -> list[str]:
    """1.1: why the page did not open, show text or run cleanly; empty if it did."""
    problems = []
    if ev["verdict"] != "ok":
        problems.append(f"verdict {ev['verdict']}")
    if ev.get("hang"):
        problems.append("hang")
    if not ev["target"].startswith(("http://", "https://")):
        problems += [f"page error: {e}" for e in ev["page_errors"]] + [f"syntax error: {e}" for e in ev["syntax_errors"]]
    return problems


def run_facts(facts_path: Path, data: list[Path]) -> tuple[list[str], list[dict], dict]:
    """1.2: problems, the facts and every fact's output."""
    try:
        facts = F.load(facts_path)
    except F.FactError as e:
        return [str(e)], [], {}
    results = F.run(facts, data)
    problems = [f"fact {i} does not run: {r['error']}" for i, r in results.items() if "error" in r]
    return problems, facts, results


def block(fact: dict, result: dict) -> str:
    tables = ", ".join(f"{name} = {path}" for name, path in fact["tables"].items())
    return f"[{fact['id']}]\nclaim: {fact['claim']}\ntables: {tables}\ncode: {fact['code']}\noutput:\n{result['output']}"


def claims_hold(facts: list[dict], results: dict, model: str) -> dict:
    """1.3: one model call over every claim, its code and its output."""
    prompt = PROMPT.replace("{facts}", "\n\n".join(block(f, results[f["id"]]) for f in facts))
    reply = LLM(model).chat([{"role": "user", "content": prompt}], max_tokens=MAX_TOKENS)
    m = re.search(r"\{.*\}", reply.text, re.S)
    try:
        verdicts = json.loads(m.group(0))["facts"]
        wrong = [v for v in verdicts if v["verdict"] != "ok"]
    except (AttributeError, json.JSONDecodeError, KeyError, TypeError):
        verdicts = wrong = None  # no usable answer is a failed check, not a pass
    return {"verdicts": verdicts, "wrong": wrong, "prompt": prompt, "reply": reply.text,
            "usage": {"prompt_tokens": reply.prompt_tokens, "completion_tokens": reply.completion_tokens, "seconds": reply.seconds}}


def trust(ev_dir: Path, facts_path: Path, model: str = MODEL) -> dict:
    """The three items for one captured page. `violated` is None for 1.3 when the model gave no usable answer."""
    ev = json.loads((ev_dir / "evidence.json").read_text(encoding="utf-8"))
    record = {"page": ev["target"], "facts": str(facts_path), "model": model, "prompt_hash": PROMPT_HASH, "items": {}}
    problems = renders(ev)
    record["items"]["1.1"] = {"violated": bool(problems), "problems": problems}
    if not problems:
        problems, facts, results = run_facts(facts_path, [Path(p) for p in ev["data"]])
        record["items"]["1.2"] = {"violated": bool(problems), "problems": problems}
        if not problems:
            check = claims_hold(facts, results, model)
            record["items"]["1.3"] = {"violated": None if check["wrong"] is None else bool(check["wrong"]), **check}
    record["vetoed"] = [k for k, v in record["items"].items() if v["violated"]]
    return record


def feedback(record: dict) -> list[str]:
    """One line per problem, in the rubric's words."""
    names = {"1.1": "页面可渲染", "1.2": "fact 能执行", "1.3": "结论和数据一致"}
    lines = [f"{k} {names[k]}:{p}" for k, v in record["items"].items() for p in v.get("problems", [])]
    check = record["items"].get("1.3")
    if check and check["wrong"] is None:
        lines.append("1.3 结论和数据一致:核对没有给出可用的结果")
    for v in (check or {}).get("wrong") or []:
        lines.append(f"1.3 结论和数据一致:[{v.get('id')}] {v.get('basis', '')}")
    return lines


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("evidence", type=Path)
    ap.add_argument("facts", type=Path)
    ap.add_argument("--model", default=MODEL)
    args = ap.parse_args()
    r = trust(args.evidence, args.facts, args.model)
    print(f"vetoed={','.join(r['vetoed']) or '-'}")
    for line in feedback(r):
        print("  " + line)
    if "1.3" in r["items"]:
        print(f"  usage {r['items']['1.3']['usage']}")


if __name__ == "__main__":
    main()

"""Read the rubric items from rubric/judge-dimensions.md.

The markdown is the only copy of the rubric: every table row that starts with an
item number ("| 2.6 | 视图连贯 | ...") is an item, with its name, its description
and how it is judged. The basis column (which labels and papers it comes from)
is for people and is not sent to the judge. A scored item also has five band
descriptions under "#### 2.6 视图连贯" in the banding section, the way MiMo's
eval rubric describes each of its dimensions. An aesthetic item adds worked
examples under its bands ("- 例 0.9 hype/original 第 3 帧:..."): a page from
runs/evidence, the frame that shows it, its score and why; the judge sees the
frame before scoring, so the bands mean the same thing on every call. An item
whose score the code computes ("程序算分", 2.2) has no bands, and an item judged
from the page's prose alone ("只看正文") is article.py's, not judge.py's.
"""

from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass
from pathlib import Path

RUBRIC = Path(__file__).resolve().parents[2] / "rubric" / "judge-dimensions.md"
ROW = re.compile(r"^\| (\d+\.\d+) \| ([^|]+) \| ([^|]+) \| ([^|]+) \|")
BAND_HEAD = re.compile(r"^#### (\d+\.\d+) ")
BAND = re.compile(r"^- (\[0\.\d, [01]\.\d[)\]]):?(.+)$")
EXAMPLE = re.compile(r"^- 例 ([01](?:\.\d+)?) ([\w-]+)/([\w-]+) 第 (\d+) 帧:(.+)$")


@dataclass(frozen=True)
class Example:
    score: float
    story: str
    version: str
    frame: int
    note: str


@dataclass(frozen=True)
class Item:
    id: str
    name: str
    description: str
    mode: str  # the rubric's own words, e.g. "门槛,代码", "打分(要按滚动位置截多帧)", "打分(照典型案例)", "打分(只看正文)"
    bands: tuple[str, ...] = ()  # five "[0.0, 0.2):..." lines for a scored item
    examples: tuple[Example, ...] = ()  # worked examples for an aesthetic item

    @property
    def banded(self) -> bool:
        """Scored by a model on five bands."""
        return "打分" in self.mode

    @property
    def scored(self) -> bool:
        """Part of the page's score: banded, or computed by the code from a model's answer."""
        return self.banded or "算分" in self.mode

    @property
    def prose_only(self) -> bool:
        """Judged from the page's prose alone (article.py), not from the screenshots (judge.py)."""
        return "只看正文" in self.mode


def load(path: Path = RUBRIC) -> dict[str, Item]:
    lines = path.read_text(encoding="utf-8").splitlines()
    bands: dict[str, list[str]] = {}
    examples: dict[str, list[Example]] = {}
    current = None
    for line in lines:
        head = BAND_HEAD.match(line)
        if head:
            current = head[1]
            bands[current] = []
            examples[current] = []
        elif current and (m := EXAMPLE.match(line)):
            examples[current].append(Example(float(m[1]), m[2], m[3], int(m[4]), m[5].strip()))
        elif current and (m := BAND.match(line)):
            bands[current].append(f"{m[1]}:{m[2].strip()}")
        elif line.startswith("#"):
            current = None
    items = {}
    for line in lines:
        m = ROW.match(line)
        if m:
            items[m[1]] = Item(m[1], m[2].strip(), m[3].strip(), m[4].strip(), tuple(bands.get(m[1], ())),
                               tuple(examples.get(m[1], ())))
    for it in items.values():
        if it.banded and len(it.bands) != 5:
            raise ValueError(f"{it.id} is scored on bands but has {len(it.bands)} band descriptions, not 5")
    return items


def rubric_hash(path: Path = RUBRIC) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()[:12]


if __name__ == "__main__":
    for it in load().values():
        kind = ("prose" if it.prose_only else "scored") if it.scored else "trust"
        print(f"{it.id:5} {kind:7} {it.name}  [{it.mode[:30]}] bands={len(it.bands)} examples={len(it.examples)}")

